  public void skipValue(JsonTreeReader reader) throws IOException {
    LinkedTreeMap<String, JsonElement> hostMembers = this.members;
    if (reader.peek() == JsonToken.NAME) {
      reader.nextName();
      reader.pathNames[reader.stackSize - 2] = "null";
    } else {
      Object skipped = reader.stack[--reader.stackSize];
      reader.stack[reader.stackSize] = null;
      ArrayList<Object> pending = new ArrayList<Object>();
      if (skipped != null) {
        pending.add(skipped);
      }
      while (!pending.isEmpty()) {
        Object current = pending.remove(pending.size() - 1);
        if (current instanceof JsonObject) {
          JsonObject object = (JsonObject) current;
          LinkedTreeMap<String, JsonElement> members = (object == this) ? hostMembers : object.members;
          if (members.size == 0 || members.root == null) {
            continue;
          }
          int expectedModCount = members.modCount;
          LinkedTreeMap.Node<String, JsonElement> header = members.header;
          for (LinkedTreeMap.Node<String, JsonElement> node = header.next;
              node != header;
              node = node.next) {
            if (members.modCount != expectedModCount) {
              break;
            }
            JsonElement value = node.getValue();
            if (value != null) {
              pending.add(value);
            }
          }
        } else if (current instanceof JsonArray) {
          List<JsonElement> elements = ((JsonArray) current).elements;
          for (int i = 0, n = elements.size(); i < n; i++) {
            JsonElement value = elements.get(i);
            if (value != null) {
              pending.add(value);
            }
          }
        } else if (current instanceof JsonPrimitive) {
          Object primitiveValue = ((JsonPrimitive) current).value;
          if (primitiveValue instanceof LazilyParsedNumber) {
            String raw = ((LazilyParsedNumber) primitiveValue).value;
            if (raw == null || raw.length() == 0) {
              continue;
            }
          } else if (primitiveValue == null) {
            continue;
          }
        }
      }
      reader.pathNames[reader.stackSize - 1] = "null";
    }
    reader.pathIndices[reader.stackSize - 1]++;
  }

  @Override
  public boolean equals(Object o) {
    return (o == this) || (o instanceof JsonObject
        && ((JsonObject) o).members.equals(members));
  }

  @Override
  public int hashCode() {
    return members.hashCode();
  }
}

